export const LNAT_BATCH = [
  // ── Passage 1: Free Speech ────────────────────────────────────────────────
  { id:'lnat_043', q:'Passage: "Free speech absolutists argue that any limitation on expression, however offensive, sets a dangerous precedent. Once we permit the state to silence one category of speech, we grant it the power to silence others. The remedy for bad speech, on this view, is more speech — not enforced silence. Critics counter that this ignores the chilling effect that hate speech has on minority communities, who may feel unable to participate in public discourse when subjected to dehumanising language."\n\nAccording to the passage, why do free speech absolutists oppose restrictions on offensive speech?', opts:['Because offensive speech is harmless','Because restricting one category of speech creates a mechanism that could be used to restrict others','Because minority communities do not participate in public discourse','Because the state has no interest in regulating expression'], ans:1, topic:'Argument Analysis', hint:'The absolutist argument, as stated, is that permitting the state to silence one category of speech grants it the power to silence others — a slippery slope / precedent argument.', difficulty:2, tags:[] },
  { id:'lnat_044', q:'Using the same passage about free speech, what is the "chilling effect" as used by critics of free speech absolutism?', opts:['The physical effect of cold weather on public gatherings','The way in which hate speech makes minority groups less willing or able to participate in public discourse','The government\'s power to imprison those who speak offensively','The emotional distress caused by political argument'], ans:1, topic:'Argument Analysis', hint:'"Chilling effect" in legal and political discourse refers to a deterrent effect on legitimate speech or participation — minorities may self-censor or withdraw from discourse if subjected to dehumanising language.', difficulty:2, tags:[] },
  { id:'lnat_045', q:'Using the same passage, which of the following best describes the structure of the argument?', opts:['The passage presents only the free speech absolutist view','The passage presents a position, then introduces a counterpoint from critics','The passage refutes both positions and introduces a third view','The passage argues that offensive speech should be banned'], ans:1, topic:'Argument Analysis', hint:'The passage presents the absolutist view first ("argue that..."), then introduces the opposing view ("Critics counter that..."). It presents two sides without advocating one — a balanced presentation of the debate.', difficulty:1, tags:[] },

  // ── Passage 2: Jury System ────────────────────────────────────────────────
  { id:'lnat_046', q:'Passage: "The jury system rests on the principle that accused persons should be judged by their peers rather than professional judges alone. Advocates argue it prevents state overreach and brings community values into the courtroom. However, juries may be susceptible to media influence, unconscious bias, and an inability to understand complex technical evidence. Some jurisdictions have responded by introducing expert juries or judge-only trials in complex fraud cases."\n\nWhat is the main argument made in favour of the jury system?', opts:['Juries are more intelligent than judges','Juries ensure defendants are judged by community members rather than the state alone','Juries are less susceptible to bias than judges','Juries are cheaper to employ than professional judges'], ans:1, topic:'Argument Analysis', hint:'The passage identifies two arguments for juries: (1) judged by peers, not the state; (2) community values. The key principle is democratic accountability — preventing state/judicial overreach.', difficulty:1, tags:[] },
  { id:'lnat_047', q:'Same passage. Which of the following most accurately summarises a weakness of the jury system as described?', opts:['Juries are too expensive to maintain','Juries may be biased, influenced by media, and lack capacity to evaluate complex evidence','Juries always prefer to acquit defendants','Juries have no legal training at all'], ans:1, topic:'Argument Analysis', hint:'The passage lists three weaknesses: media influence, unconscious bias, and inability to understand complex technical evidence. Option B captures all three dimensions of the weakness argument.', difficulty:1, tags:[] },
  { id:'lnat_048', q:'Same passage. What does the passage imply about judge-only trials in fraud cases?', opts:['They are unconstitutional','They represent a complete abandonment of the jury principle in all cases','They are a pragmatic response to the specific weakness of juries in handling complex technical evidence','They are used in all serious criminal cases'], ans:2, topic:'Argument Analysis', hint:'The passage says some jurisdictions have introduced judge-only trials "in complex fraud cases" — this is framed as a targeted response to one specific weakness (technical complexity), not a wholesale abandonment of juries.', difficulty:2, tags:[] },

  // ── Passage 3: Climate Change Policy ─────────────────────────────────────
  { id:'lnat_049', q:'Passage: "Carbon taxes place a price on carbon emissions, creating an incentive for businesses and consumers to reduce their carbon footprint. Critics argue that carbon taxes are regressive — they disproportionately burden lower-income households who spend a higher proportion of their income on energy and fuel. Proponents respond that revenues can be returned to citizens as dividends, making the policy progressive in net terms. The effectiveness of the policy depends critically on how revenue is used."\n\nAccording to the passage, what is meant by calling a carbon tax "regressive"?', opts:['That it moves backwards rather than forwards','That it unfairly burdens lower-income households more than wealthier ones in proportional terms','That it reduces economic growth','That it fails to reduce carbon emissions'], ans:1, topic:'Argument Analysis', hint:'A regressive tax takes a larger proportion of income from lower-income earners. The passage states: lower-income households "spend a higher proportion of their income on energy and fuel" — so the tax hits them harder proportionally.', difficulty:1, tags:[] },
  { id:'lnat_050', q:'Same passage. What does the proponent\'s response suggest about a well-designed carbon tax?', opts:['It can eliminate all carbon emissions immediately','If revenues are redistributed as dividends, it can actually benefit lower-income households in net terms','Taxes are always regressive regardless of how revenue is used','Carbon taxes should not apply to lower-income households'], ans:1, topic:'Argument Analysis', hint:'"Revenues returned as dividends" means poorer households could receive more back than they pay — making the policy progressive overall. The net effect depends on redistribution.', difficulty:2, tags:[] },
  { id:'lnat_051', q:'Same passage. Which statement is best supported by the passage?', opts:['Carbon taxes are definitively the best climate policy','The effectiveness of a carbon tax is at least partly determined by how revenues are deployed','Carbon taxes are too complex to implement fairly','All economists oppose carbon taxes'], ans:1, topic:'Argument Analysis', hint:'The final sentence explicitly states "effectiveness depends critically on how revenue is used" — directly supporting option B. No definitive endorsement or rejection of carbon taxes is made.', difficulty:1, tags:[] },

  // ── Passage 4: Judicial Review ────────────────────────────────────────────
  { id:'lnat_052', q:'Passage: "Judicial review allows courts to scrutinise the decisions of government bodies to ensure they are lawful, rational, and procedurally fair. It is a cornerstone of the rule of law. However, some politicians argue that unelected judges should not have the power to frustrate decisions made by democratically elected representatives. This tension between legality and democratic legitimacy is one of the defining constitutional debates in the United Kingdom."\n\nWhat is judicial review, according to the passage?', opts:['A process by which judges are assessed for fitness to serve','A mechanism allowing courts to review and potentially strike down unlawful government decisions','A parliamentary committee that reviews legislation','A process by which citizens can appeal court decisions'], ans:1, topic:'Argument Analysis', hint:'The passage defines judicial review as allowing courts to scrutinise government decisions for lawfulness, rationality, and procedural fairness. It is directed at government bodies, not at judicial appointments.', difficulty:1, tags:[] },
  { id:'lnat_053', q:'Same passage. What is the tension described in the passage?', opts:['Between senior and junior judges','Between legality — courts ensuring government acts lawfully — and democratic legitimacy — elected representatives making decisions','Between the UK and European courts','Between criminal and civil law'], ans:1, topic:'Argument Analysis', hint:'The passage explicitly describes "the tension between legality and democratic legitimacy" — courts (unelected) constraining elected governments. This is the central constitutional debate identified.', difficulty:1, tags:[] },
  { id:'lnat_054', q:'Same passage. Which of the following would MOST strengthen the argument of politicians who oppose judicial review?', opts:['Evidence that judges are highly trained lawyers','Evidence that democratically passed legislation was overturned on a technicality despite wide public support','Evidence that judicial review rarely succeeds','Evidence that the courts act very quickly'], ans:1, topic:'Argument Analysis', hint:'The politicians\' argument is that unelected judges should not frustrate democratic decisions. If a widely popular, democratically passed law was overturned on a technical ground, that would most powerfully support their concern.', difficulty:2, tags:[] },

  // ── Passage 5: Universal Healthcare ──────────────────────────────────────
  { id:'lnat_055', q:'Passage: "Universal healthcare systems, such as the NHS, guarantee treatment based on clinical need rather than ability to pay. Supporters argue this is both morally required — illness should not be a financial catastrophe — and economically efficient, eliminating the administrative overhead of private insurance. Critics argue that without price signals, patients over-consume health services, leading to rationing. The debate reflects fundamental disagreements about the role of the state and the nature of rights."\n\nWhich argument do supporters of universal healthcare make on efficiency grounds?', opts:['Private healthcare is always more expensive','Universal systems eliminate the administrative costs associated with insurance systems','Universal healthcare removes all waiting lists','Universal healthcare prevents all over-consumption'], ans:1, topic:'Argument Analysis', hint:'The passage says universal systems are "economically efficient, eliminating the administrative overhead of private insurance." This is the efficiency argument — not the moral one.', difficulty:1, tags:[] },
  { id:'lnat_056', q:'Same passage. What is the critics\' main economic concern about universal healthcare?', opts:['Doctors are paid too much','Without price signals, patients may over-use services, necessitating rationing','Private hospitals are more efficient','Universal systems cost too little'], ans:1, topic:'Argument Analysis', hint:'The critics\' argument is that without the price mechanism (co-payments, insurance premiums), demand for healthcare is unconstrained, leading to over-consumption and the need for rationing.', difficulty:1, tags:[] },
  { id:'lnat_057', q:'Same passage. What does the final sentence suggest about the healthcare debate?', opts:['The debate is primarily about medical outcomes','The debate is essentially technical and will be resolved by evidence','The debate reflects deep ideological differences about the role of government and rights','All countries should adopt the same healthcare model'], ans:2, topic:'Argument Analysis', hint:'"Fundamental disagreements about the role of the state and the nature of rights" — the final sentence frames the debate as philosophical and ideological rather than purely empirical or technical.', difficulty:2, tags:[] },

  // ── Passage 6: Social Media and Democracy ────────────────────────────────
  { id:'lnat_058', q:'Passage: "Social media has transformed political communication. It enables direct engagement between politicians and citizens, bypassing traditional gatekeepers such as editors and journalists. However, the same technology facilitates the rapid spread of misinformation and allows algorithmic micro-targeting of divisive content, which some researchers argue has contributed to political polarisation. The relationship between social media and democratic health is deeply contested among political scientists."\n\nWhat advantage of social media is identified in the passage?', opts:['It prevents the spread of misinformation','It allows politicians to bypass traditional editorial gatekeepers and communicate directly with citizens','It eliminates political polarisation','It improves the quality of journalism'], ans:1, topic:'Argument Analysis', hint:'The passage identifies: direct engagement between politicians and citizens, bypassing editors/journalists. The "however" signals this will be followed by a counterpoint.', difficulty:1, tags:[] },
  { id:'lnat_059', q:'Same passage. What concern do "some researchers" raise about social media?', opts:['That it makes politicians too accessible','That algorithmic micro-targeting of divisive content may increase political polarisation','That traditional journalism is too powerful','That social media reduces voter turnout'], ans:1, topic:'Argument Analysis', hint:'The passage states "some researchers argue" that micro-targeting of divisive content "has contributed to political polarisation." This is the researchers\' concern, not an established fact.', difficulty:1, tags:[] },
  { id:'lnat_060', q:'Same passage. The phrase "deeply contested among political scientists" suggests:', opts:['Political scientists all agree social media is harmful','There is no evidence about the effects of social media on democracy','There is genuine academic disagreement about how social media affects democratic processes','Social media should be banned from political use'], ans:2, topic:'Argument Analysis', hint:'"Deeply contested" means there is significant disagreement among experts — different researchers have different findings or interpretations. It signals uncertainty and ongoing debate.', difficulty:1, tags:[] },

  // ── Passage 7: Capital Punishment ────────────────────────────────────────
  { id:'lnat_061', q:'Passage: "Capital punishment is irreversible. Unlike imprisonment, an execution cannot be undone should new evidence emerge. Given the documented fallibility of criminal justice systems — innocent people have been executed in jurisdictions that still practise it — this finality is a powerful argument against its use. Proponents argue that some crimes are so grave that death is the only proportionate response, and that the certainty of death may deter potential murderers more effectively than imprisonment."\n\nWhat is the central argument AGAINST capital punishment in the passage?', opts:['It is too expensive','Its irreversibility means that executing an innocent person cannot be corrected','It is not proportionate to any crime','It is not supported by the public'], ans:1, topic:'Argument Analysis', hint:'The argument is: (1) executions are irreversible; (2) justice systems can and do make errors; (3) therefore innocent people may be executed with no remedy. Irreversibility + fallibility = the core argument.', difficulty:1, tags:[] },
  { id:'lnat_062', q:'Same passage. The passage says "innocent people have been executed." What role does this claim play in the argument?', opts:['It is a hypothetical used to illustrate a theoretical risk','It is an empirical premise supporting the claim that the irreversibility of execution is a serious practical risk','It is the conclusion of the argument','It is irrelevant to the discussion of capital punishment'], ans:1, topic:'Argument Analysis', hint:'It is an empirical premise — evidence that the theoretical risk of executing the innocent has already materialised. It transforms the argument from theoretical to practical.', difficulty:2, tags:[] },
  { id:'lnat_063', q:'Same passage. The deterrence argument in favour of capital punishment claims:', opts:['That death is always a proportionate response to crime','That the certainty of execution may more effectively prevent murder than the prospect of imprisonment','That public executions build community trust','That the death penalty has been proven by research to deter crime'], ans:1, topic:'Argument Analysis', hint:'The passage states proponents argue "the certainty of death may deter potential murderers more effectively than imprisonment." Note: it says "may" — not proven. The deterrence argument is asserted, not evidenced, in this passage.', difficulty:2, tags:[] },

  // ── Passage 8: Immigration ────────────────────────────────────────────────
  { id:'lnat_064', q:'Passage: "Immigration has historically been a net economic benefit to receiving countries. Migrants typically fill labour market shortages, pay taxes, and contribute to innovation — a disproportionate number of start-up founders in major economies are immigrants or children of immigrants. However, the distributional effects are uneven: while aggregate GDP rises, low-skilled native workers in sectors with high migrant concentration may face wage competition. Public concern about immigration often focuses on cultural identity as much as economics."\n\nAccording to the passage, which of the following is described as a potential negative consequence of immigration?', opts:['A reduction in GDP','Increased innovation and new businesses','Wage competition for low-skilled native workers in affected sectors','A decline in tax revenues'], ans:2, topic:'Argument Analysis', hint:'The passage notes: "low-skilled native workers in sectors with high migrant concentration may face wage competition." This is explicitly identified as an uneven distributional effect.', difficulty:1, tags:[] },
  { id:'lnat_065', q:'Same passage. What does "distributional effects are uneven" mean in context?', opts:['Immigration affects all regions equally','While immigration raises overall GDP, the costs and benefits are not shared equally across all groups in society','Immigration only benefits employers','Immigrants themselves suffer from distributional problems'], ans:1, topic:'Argument Analysis', hint:'"Distributional effects are uneven" means the economic gains from immigration are not equally distributed — aggregate GDP rises but some low-skilled native workers bear the downside while business owners and the economy overall benefit.', difficulty:2, tags:[] },
  { id:'lnat_066', q:'Same passage. What does the passage suggest about the public\'s concerns regarding immigration?', opts:['That they are entirely economically rational','That public concerns are limited to wage competition','That public concerns extend beyond economics to questions of cultural identity','That the public is indifferent to immigration'], ans:2, topic:'Argument Analysis', hint:'The final sentence: "Public concern about immigration often focuses on cultural identity as much as economics." This broadens the frame — the debate is not only economic.', difficulty:1, tags:[] },

  // ── Passage 9: Artificial Intelligence and Employment ─────────────────────
  { id:'lnat_067', q:'Passage: "Automation and artificial intelligence are transforming labour markets. Routine cognitive tasks — data entry, basic analysis, some forms of diagnosis — are increasingly performed by machines. While historical waves of automation have always created new jobs to replace those destroyed, some economists argue this time is different: the pace of change exceeds the capacity of workers to retrain, and machines are encroaching on tasks previously considered uniquely human. The social consequences of mass technological unemployment, if it occurs, could be profound."\n\nWhat is the standard historical argument against fears of technological unemployment?', opts:['That machines always make mistakes','That previous automation always ultimately created more jobs than it destroyed','That workers have always been able to retrain quickly','That governments have always successfully managed unemployment'], ans:1, topic:'Argument Analysis', hint:'"Historical waves of automation have always created new jobs to replace those destroyed" — this is the standard counterargument to fears of permanent technological unemployment.', difficulty:1, tags:[] },
  { id:'lnat_068', q:'Same passage. Why do some economists argue that current AI is different from past automation?', opts:['Because AI is more expensive to develop','Because the pace of change is too fast for workers to retrain, and machines are now doing tasks previously considered uniquely human','Because current automation only affects manufacturing','Because previous automation was government-funded'], ans:1, topic:'Argument Analysis', hint:'Two reasons given: (1) pace exceeds retraining capacity; (2) machines are now doing "uniquely human" tasks (cognitive work). Both distinguish current AI from previous mechanical automation.', difficulty:2, tags:[] },
  { id:'lnat_069', q:'Same passage. The phrase "if it occurs" in the final sentence is significant because:', opts:['It suggests the author believes mass unemployment is inevitable','It indicates the author is unsure whether mass unemployment will actually happen, maintaining appropriate uncertainty','It is a grammatical filler with no meaning','It suggests the author is opposed to AI development'], ans:1, topic:'Argument Analysis', hint:'"If it occurs" is a conditional — the author is not asserting mass technological unemployment will happen, only that IF it does, the social consequences would be profound. Appropriate epistemic caution.', difficulty:2, tags:[] },

  // ── Passage 10: Animal Rights ─────────────────────────────────────────────
  { id:'lnat_070', q:'Passage: "The philosopher Peter Singer argues that the capacity to suffer, not intelligence or species membership, should determine moral consideration. If an animal can suffer, it has a morally relevant interest in not suffering that we must weigh equally to the suffering of humans. This view, known as preference utilitarianism, has radical implications: it challenges the moral permissibility of factory farming, animal experimentation, and other practices that cause animal suffering for human benefit."\n\nWhat is Singer\'s primary criterion for moral consideration?', opts:['Intelligence','Species membership','The capacity to suffer','Membership of the human species'], ans:2, topic:'Argument Analysis', hint:'"The capacity to suffer, not intelligence or species membership" — Singer\'s utilitarian criterion is sentience (the ability to feel pain/pleasure). This is the key principle of preference utilitarianism.', difficulty:1, tags:[] },
  { id:'lnat_071', q:'Same passage. What does "equal consideration" mean in Singer\'s framework, as described?', opts:['That all animals should be treated identically to humans','That the suffering of a cow and a human must be treated as equally morally relevant when weighing interests','That only humans deserve equal treatment under law','That animals and humans have the same cognitive capacities'], ans:1, topic:'Argument Analysis', hint:'"Morally relevant interest in not suffering that we must weigh equally" — equal consideration means equal weight given to equivalent suffering, not identical treatment. A pig\'s suffering counts as much as human suffering of the same intensity.', difficulty:2, tags:[] },
  { id:'lnat_072', q:'Same passage. Why does the passage describe Singer\'s view as having "radical implications"?', opts:['Because Singer advocates extreme political revolution','Because applying the equal consideration principle consistently would require abandoning widely practised activities such as factory farming and animal experimentation','Because preference utilitarianism is a very new philosophical idea','Because Singer believes all animals should have voting rights'], ans:1, topic:'Argument Analysis', hint:'"Radical implications" refers to what follows logically from the principle: if animal suffering matters equally, then practices causing large-scale animal suffering for human convenience (factory farming, experimentation) become morally impermissible.', difficulty:2, tags:[] },

  // ── Passage 11: The Rule of Law ───────────────────────────────────────────
  { id:'lnat_073', q:'Passage: "The rule of law requires that all individuals and institutions, including the government, are accountable to laws that are publicly promulgated, equally enforced, and independently adjudicated. It is distinct from rule by law — where law is used as an instrument of government power rather than a constraint upon it. The rule of law is widely regarded as a prerequisite for democracy, human rights protection, and economic development."\n\nAccording to the passage, what distinguishes "rule of law" from "rule by law"?', opts:['Rule of law applies to individuals; rule by law applies to governments','In rule of law, the government itself is constrained by law; in rule by law, the government uses law as a tool of power rather than being bound by it','Rule of law is democratic; rule by law is authoritarian by definition','They are synonyms used interchangeably in legal theory'], ans:1, topic:'Argument Analysis', hint:'The passage explicitly distinguishes the two: rule of law = law constrains government; rule by law = government uses law as an instrument. The key difference is whether law applies to, or is used by, the powerful.', difficulty:2, tags:[] },
  { id:'lnat_074', q:'Same passage. Which of the following is NOT listed as a requirement of the rule of law?', opts:['Public promulgation of laws','Equal enforcement','Independent adjudication','Laws written by elected representatives'], ans:3, topic:'Argument Analysis', hint:'The passage lists three requirements: publicly promulgated (publicly known), equally enforced, and independently adjudicated. Who writes the laws (elected representatives) is not listed as a requirement.', difficulty:2, tags:[] },
  { id:'lnat_075', q:'Same passage. Which of the following, if true, would be an example of rule by law rather than rule of law?', opts:['A government that publishes all its laws openly','A court that applies law equally to both government officials and citizens','A government that passes laws specifically to imprison political opponents','A government that reduces the powers of courts to protect individual rights'], ans:2, topic:'Argument Analysis', hint:'Rule by law = law as an instrument of power. A government using legislation to imprison political opponents is weaponising law against those it opposes — using it as a tool, not being constrained by it.', difficulty:2, tags:[] },

  // ── Passage 12: Populism ─────────────────────────────────────────────────
  { id:'lnat_076', q:'Passage: "Populism is a political style that frames politics as a struggle between a virtuous \'people\' and a corrupt \'elite\'. It is not inherently right or left-wing — populist movements have emerged across the political spectrum. Critics argue that populism is dangerous because it delegitimises political opponents, undermines independent institutions, and oversimplifies complex policy problems. Defenders contend that populism gives voice to legitimate grievances ignored by political establishments."\n\nAccording to the passage, is populism exclusively a right-wing phenomenon?', opts:['Yes — the passage states it is primarily right-wing','No — the passage states it has emerged across the political spectrum','The passage does not address whether populism is right or left-wing','Yes — all examples of populism described are from the right'], ans:1, topic:'Argument Analysis', hint:'"Not inherently right or left-wing — populist movements have emerged across the political spectrum." Explicitly contradicts the idea that populism is exclusively right-wing.', difficulty:1, tags:[] },
  { id:'lnat_077', q:'Same passage. What is the critics\' concern about populism and institutions?', opts:['That populism creates too many new institutions','That populism undermines independent institutions','That populism relies too heavily on judicial review','That populism leads to better governance'], ans:1, topic:'Argument Analysis', hint:'Critics list three concerns: delegitimising opponents, undermining independent institutions (courts, press, civil service), and oversimplifying policy. The concern about institutions is explicit.', difficulty:1, tags:[] },
  { id:'lnat_078', q:'Same passage. Which of the following best represents the defenders\' argument for populism?', opts:['That populism always improves economic outcomes','That populism gives a voice to genuine public concerns that mainstream politics has failed to address','That populist leaders are always more honest than establishment politicians','That populism is the most stable form of government'], ans:1, topic:'Argument Analysis', hint:'Defenders say populism "gives voice to legitimate grievances ignored by political establishments." This is the normative defence — that populism corrects a democratic deficit.', difficulty:1, tags:[] },

  // ── Passage 13: Intellectual Property ────────────────────────────────────
  { id:'lnat_079', q:'Passage: "Intellectual property (IP) law grants creators temporary monopoly rights over their work, allowing them to recoup investment and profit from innovation. Without such protections, free-riding by competitors could undermine incentives to create. However, IP rights can also restrict access to essential goods — the patent system has been criticised for making life-saving medicines unaffordable in developing countries. Balancing incentives to innovate against broad access is a fundamental tension in IP policy."\n\nWhy does the passage suggest IP law is necessary?', opts:['To give the state control over creative works','To prevent free-riding by competitors, which would otherwise undermine the incentive to invest in creation and innovation','To restrict access to information','To ensure all inventions are in the public domain'], ans:1, topic:'Argument Analysis', hint:'"Without such protections, free-riding by competitors could undermine incentives to create." The economic argument is: IP rights create financial incentives for innovation by protecting returns on investment.', difficulty:1, tags:[] },
  { id:'lnat_080', q:'Same passage. How has the patent system been criticised?', opts:['For being too weak to protect inventors','For making life-saving medicines too expensive for developing countries','For preventing scientific publication','For lasting too long in time'], ans:1, topic:'Argument Analysis', hint:'Explicitly stated: "the patent system has been criticised for making life-saving medicines unaffordable in developing countries." Patents on pharmaceuticals enable companies to charge high prices.', difficulty:1, tags:[] },
  { id:'lnat_081', q:'Same passage. Which of the following best captures the "fundamental tension" described?', opts:['Between national and international law','Between providing incentives to innovate and ensuring broad access to the outputs of innovation','Between copyright and patent law','Between short and long IP protection terms'], ans:1, topic:'Argument Analysis', hint:'"Balancing incentives to innovate against broad access" — this is explicitly described as the fundamental tension. Innovation incentives (monopoly rights) vs access (allowing others to use without payment).', difficulty:1, tags:[] },

  // ── Passage 14: Privacy and Surveillance ─────────────────────────────────
  { id:'lnat_082', q:'Passage: "Mass surveillance programmes, such as those revealed by Edward Snowden in 2013, raise profound questions about the relationship between security and liberty. Governments argue that large-scale data collection is necessary to identify and disrupt terrorist networks before attacks occur. Civil liberties organisations counter that mass surveillance is disproportionate — the privacy of millions is violated to identify a handful of suspects — and that it has a chilling effect on free expression and political dissent."\n\nWhat justification do governments give for mass surveillance?', opts:['To monitor political opponents','To identify and prevent terrorist attacks before they occur','To reduce petty crime','To comply with international law'], ans:1, topic:'Argument Analysis', hint:'"Necessary to identify and disrupt terrorist networks before attacks occur" — the security justification is prevention of terrorism. This is the classic security-liberty trade-off argument.', difficulty:1, tags:[] },
  { id:'lnat_083', q:'Same passage. What does "disproportionate" mean in the civil liberties argument?', opts:['That surveillance is too expensive','That the privacy violation suffered by millions outweighs the security benefit of identifying a small number of suspects','That surveillance should only target known criminals','That surveillance is ineffective at identifying terrorists'], ans:1, topic:'Argument Analysis', hint:'"Disproportionality" is a legal concept: the harm caused (mass privacy violation) must be proportionate to the benefit gained (identifying a few suspects). The argument is that it is not proportionate.', difficulty:2, tags:[] },
  { id:'lnat_084', q:'Same passage. The passage states surveillance has a "chilling effect on free expression and political dissent." This means:', opts:['That surveillance physically prevents people from speaking','That the knowledge of being monitored may deter people from expressing dissenting or controversial views','That surveillance freezes all political activity','That dissent leads to criminal prosecutions in all cases'], ans:1, topic:'Argument Analysis', hint:'"Chilling effect" — knowing you are monitored, people may self-censor legitimate political speech, not because it is illegal but because of the perceived risk. This constrains free expression even without direct suppression.', difficulty:2, tags:[] },

  // ── Passage 15: Philosophy of Rights ─────────────────────────────────────
  { id:'lnat_085', q:'Passage: "Natural rights theorists hold that individuals possess certain fundamental rights simply by virtue of being human — rights that pre-exist and are not granted by the state. These rights act as constraints on what governments may do. Positive rights theorists counter that rights without corresponding duties and the means to fulfil them are empty. The right to food means nothing if you have no means to obtain it. Both traditions shape modern human rights law."\n\nAccording to natural rights theory as described, where do rights come from?', opts:['From legislation passed by parliaments','From cultural traditions and norms','From the nature of human beings themselves — they pre-exist the state','From international treaties'], ans:2, topic:'Argument Analysis', hint:'"Individuals possess certain fundamental rights simply by virtue of being human... rights that pre-exist and are not granted by the state." Rights are inherent in human nature, not conferred.', difficulty:1, tags:[] },
  { id:'lnat_086', q:'Same passage. What is the positive rights theorists\' criticism of natural rights theory?', opts:['That natural rights are too many','That rights without corresponding duties and the ability to fulfil them are meaningless in practice','That natural rights are anti-democratic','That natural rights conflict with international law'], ans:1, topic:'Argument Analysis', hint:'"Rights without corresponding duties and the means to fulfil them are empty." If you have a right to food but no means to obtain it and no one has a duty to provide it, the right is effectively worthless.', difficulty:2, tags:[] },
  { id:'lnat_087', q:'Same passage. The example of "the right to food" is used to illustrate:', opts:['That food security is the most important human right','That natural rights theorists oppose economic rights','The positive rights argument that a right is only meaningful if someone has a duty to ensure it can be exercised','That both traditions agree on the right to food'], ans:2, topic:'Argument Analysis', hint:'The food example illustrates the positive rights critique: rights need corresponding duties AND the means to fulfil them. Without these, rights are nominal, not real. The example grounds an abstract philosophical point in a concrete case.', difficulty:2, tags:[] },

  // ── Passage 16: Legal Interpretation ─────────────────────────────────────
  { id:'lnat_088', q:'Passage: "Statutory interpretation is the process by which courts give meaning to legislation. Literalist judges apply the ordinary meaning of words; purposive judges look beyond the text to the intention of Parliament. The literal approach risks absurd results when words are applied rigidly; the purposive approach risks judges substituting their view of Parliament\'s intention for Parliament\'s actual words. Both approaches reflect deeper disagreements about the appropriate role of judges in a democracy."\n\nWhat is the main risk of the literal approach?', opts:['That judges gain too much power','That applying words rigidly can lead to outcomes that are absurd or clearly contrary to common sense','That legislation is too long to read literally','That the literal approach gives no guidance to future cases'], ans:1, topic:'Argument Analysis', hint:'"The literal approach risks absurd results when words are applied rigidly." If a statute says "no vehicles in the park" and a judge rules a child\'s toy pedal car is a vehicle, that may be literal but absurd.', difficulty:1, tags:[] },
  { id:'lnat_089', q:'Same passage. What is the main risk of the purposive approach?', opts:['That it leads to more consistent outcomes','That judges may effectively rewrite legislation by substituting their view of Parliament\'s intention for its actual words','That it makes statutory interpretation too slow','That it produces absurd results'], ans:1, topic:'Argument Analysis', hint:'"Judges substituting their view of Parliament\'s intention for Parliament\'s actual words." The danger is judicial overreach — judges deciding what Parliament meant, which may differ from what Parliament said.', difficulty:1, tags:[] },
  { id:'lnat_090', q:'Same passage. What broader question do both interpretive approaches reflect, according to the passage?', opts:['Whether judges should be elected','Disagreements about the appropriate constitutional role of unelected judges in a democracy','Whether legislation should be written more clearly','Whether courts should have greater resources'], ans:1, topic:'Argument Analysis', hint:'"Both approaches reflect deeper disagreements about the appropriate role of judges in a democracy." How much should unelected judges fill gaps in legislation vs. leaving it to elected Parliament?', difficulty:2, tags:[] },

  // ── Passage 17: Education Policy ─────────────────────────────────────────
  { id:'lnat_091', q:'Passage: "Grammar schools select pupils at age 11 on academic ability. Supporters argue they provide pathways for talented children from disadvantaged backgrounds to access elite education. Critics contend that the evidence shows grammar schools primarily benefit middle-class families who can afford tutoring for the entrance test, and that they worsen outcomes for those who fail selection. The debate reflects competing conceptions of equality — equality of opportunity versus equality of outcome."\n\nAccording to supporters of grammar schools, how do they benefit disadvantaged children?', opts:['By providing free tutoring for all pupils','By creating pathways for academically talented children from disadvantaged backgrounds to access elite education','By abolishing entrance tests','By mixing pupils of all ability levels together'], ans:1, topic:'Argument Analysis', hint:'"Provide pathways for talented children from disadvantaged backgrounds to access elite education." The argument is meritocratic — talent, not background, should determine access.', difficulty:1, tags:[] },
  { id:'lnat_092', q:'Same passage. What does the evidence cited by critics suggest?', opts:['That all children benefit equally from grammar schools','That grammar schools primarily benefit middle-class families who can afford test preparation, and harm those who fail selection','That grammar schools are fully comprehensive in their intake','That grammar school pupils perform worse at A-level'], ans:1, topic:'Argument Analysis', hint:'Critics point to two empirical claims: (1) primary beneficiaries are middle-class families (who can afford tutoring); (2) those who fail selection suffer worse outcomes. This undermines the equality-of-opportunity claim.', difficulty:1, tags:[] },
  { id:'lnat_093', q:'Same passage. What does "equality of opportunity versus equality of outcome" mean in this context?', opts:['Whether all pupils sit the same exams','Whether the education system should give everyone an equal chance (even if results differ) or aim to produce more equal outcomes regardless of initial ability','Whether school funding should be equal','Whether teachers should be paid equally'], ans:1, topic:'Argument Analysis', hint:'Equality of opportunity: give everyone a fair chance to compete (grammar schools: open to all, select on merit). Equality of outcome: reduce gaps between what different groups achieve (selective schools may increase inequality of outcomes for non-selected pupils).', difficulty:2, tags:[] },

  // ── Passage 18: Punishment Theory ────────────────────────────────────────
  { id:'lnat_094', q:'Passage: "Theories of punishment divide broadly into retributive and consequentialist approaches. Retributivists hold that punishment is justified because wrongdoers deserve it — it is intrinsically right to punish proportionately to the crime, regardless of consequences. Consequentialists justify punishment only if it produces good outcomes: deterrence, rehabilitation, or incapacitation of those likely to reoffend. A purely retributive system might impose severe punishment even where it does no practical good; a purely consequentialist one might justify punishing the innocent if it produced sufficient deterrent effect."\n\nWhat is the retributive justification for punishment?', opts:['Punishment is justified because it deters future crime','Punishment is justified because wrongdoers deserve it — it is intrinsically right to respond proportionately to wrongdoing','Punishment is justified by its rehabilitative effect','Punishment is justified only if it improves public safety'], ans:1, topic:'Argument Analysis', hint:'"Wrongdoers deserve it — it is intrinsically right to punish proportionately to the crime, regardless of consequences." Retributivism is backward-looking: punishment is a response to what was done, not a means to future ends.', difficulty:1, tags:[] },
  { id:'lnat_095', q:'Same passage. What is the danger of a purely consequentialist theory of punishment?', opts:['That it would abolish punishment entirely','That it could in principle justify punishing an innocent person if doing so produced a sufficient deterrent effect','That it ignores the severity of individual crimes','That it leads to very long prison sentences'], ans:1, topic:'Argument Analysis', hint:'"A purely consequentialist one might justify punishing the innocent if it produced sufficient deterrent effect." If punishment is judged only by outcomes, and punishing an innocent scapegoat produces better deterrence, the theory logically permits it.', difficulty:2, tags:[] },
  { id:'lnat_096', q:'Same passage. A sentencing judge says: "I sentence you to 5 years not because you deserve it, but because it will prevent you and others from committing similar crimes." Which theory is the judge using?', opts:['Retributive','Consequentialist','Restorative','Natural law'], ans:1, topic:'Argument Analysis', hint:'"Not because you deserve it, but because it will prevent..." — forward-looking, outcome-focused justification. This is explicitly consequentialist: deterrence and incapacitation are consequentialist goals.', difficulty:2, tags:[] },

  // ── Passage 19: Constitutional Conventions ────────────────────────────────
  { id:'lnat_097', q:'Passage: "Constitutional conventions are non-legal rules that constrain the exercise of legal powers by constitutional actors. They are not enforced by courts, yet they are considered binding in a normative sense — breach is a constitutional wrong, even if not a legal one. The convention that the monarch accepts the advice of ministers is an example: the monarch retains the legal power to refuse, but doing so would be constitutionally impermissible. Conventions rely on consensus and mutual restraint for their effectiveness."\n\nWhat distinguishes constitutional conventions from laws?', opts:['Conventions are written down; laws are oral','Conventions are enforced by courts; laws are not','Conventions are not enforceable by courts but are still considered binding as a matter of constitutional practice','Conventions apply only to the monarchy; laws apply to everyone'], ans:2, topic:'Argument Analysis', hint:'"Not enforced by courts, yet considered binding in a normative sense." They are politically and constitutionally binding without legal enforceability — the key distinction from law.', difficulty:2, tags:[] },
  { id:'lnat_098', q:'Same passage. What makes conventions effective despite not being legally enforceable?', opts:['Fear of prosecution','Financial penalties for breach','Consensus and mutual restraint among constitutional actors','Formal written constitutions'], ans:2, topic:'Argument Analysis', hint:'"Conventions rely on consensus and mutual restraint for their effectiveness." They work because constitutional actors agree to respect them and exercise self-restraint — not because of external legal compulsion.', difficulty:1, tags:[] },
  { id:'lnat_099', q:'Same passage. If a monarch refused to accept ministerial advice, this would be:', opts:['A legal wrong enforceable in court','A constitutional wrong — a breach of convention — but not a legal wrong','Entirely permissible under the constitution','A criminal offence under statute'], ans:1, topic:'Argument Analysis', hint:'"Constitutionally impermissible" but the monarch "retains the legal power to refuse." So the refusal would be a constitutional wrong (breach of convention) but not a legal wrong (no law broken that a court would enforce).', difficulty:2, tags:[] },

  // ── Passage 20: Contract Law ──────────────────────────────────────────────
  { id:'lnat_100', q:'Passage: "A contract requires offer, acceptance, and consideration to be legally binding. Consideration is something of value exchanged between the parties — it need not be adequate (fair market value) but must be sufficient (of some legal value). A promise to pay for something already done (past consideration) is generally not valid consideration. The doctrine of promissory estoppel can, however, prevent a party from going back on a clear promise where the other party has relied on it to their detriment."\n\nWhat are the three essential elements of a contract?', opts:['Offer, promise, and signature','Offer, acceptance, and consideration','Agreement, payment, and witnesses','Capacity, intention, and a written document'], ans:1, topic:'Argument Analysis', hint:'"A contract requires offer, acceptance, and consideration." These are the three classical elements of a binding contract in English law.', difficulty:1, tags:[] },
  { id:'lnat_101', q:'Same passage. Why is "past consideration" not valid?', opts:['Because past events are too difficult to prove','Because the law requires consideration to be something exchanged as part of the current bargain, not something already done before any promise was made','Because past consideration is always inadequate in value','Because past events are barred by the statute of limitations'], ans:1, topic:'Argument Analysis', hint:'Consideration must be part of the current bargain. "I\'ll pay you £100 for fixing my car last week" — the car has already been fixed; the consideration was past and cannot support a new promise.', difficulty:2, tags:[] },
  { id:'lnat_102', q:'Same passage. When does promissory estoppel apply?', opts:['Whenever any promise is broken','Where a clear promise was made and the other party detrimentally relied on it, preventing the promisor from going back on the promise','Where consideration is inadequate','Where a written contract was not signed'], ans:1, topic:'Argument Analysis', hint:'"Prevent a party from going back on a clear promise where the other party has relied on it to their detriment." Two conditions: (1) clear promise; (2) detrimental reliance. It operates as an equitable doctrine to prevent injustice.', difficulty:2, tags:[] },

  // ── Passage 21: Precedent ────────────────────────────────────────────────
  { id:'lnat_103', q:'Passage: "The doctrine of precedent (stare decisis) requires courts to follow decisions of higher courts in their hierarchy. The binding part of a judgment is the ratio decidendi — the legal reasoning necessary to the decision. Obiter dicta — things said in passing — are not binding, though they may be persuasive. The House of Lords (now Supreme Court) may depart from its own previous decisions in exceptional circumstances where it is right to do so."\n\nWhat is the ratio decidendi?', opts:['The judge\'s personal opinion on the law','Things said in passing that are not essential to the decision','The legal reasoning that was necessary and decisive in reaching the court\'s decision','The dissenting opinion of minority judges'], ans:2, topic:'Argument Analysis', hint:'"The legal reasoning necessary to the decision" — it is the core legal principle that the court relied upon to reach its verdict. Only this part is binding on lower courts.', difficulty:1, tags:[] },
  { id:'lnat_104', q:'Same passage. What is the difference between binding and persuasive precedent?', opts:['Binding precedent must be followed; persuasive precedent (like obiter dicta) may be considered but need not be followed','Binding precedent is from lower courts; persuasive precedent is from higher courts','Both binding and persuasive precedent must be followed by all courts','There is no difference — all precedent is treated equally'], ans:0, topic:'Argument Analysis', hint:'Binding precedent (from higher courts\' ratio) must be followed. Persuasive (obiter dicta, decisions from equivalent or foreign courts) may be considered and adopted but is not compulsory.', difficulty:1, tags:[] },
  { id:'lnat_105', q:'Same passage. The Supreme Court\'s ability to depart from its own precedent suggests:', opts:['That the doctrine of precedent does not apply to the Supreme Court at all','That the law must be capable of development and correction even at the highest level, though stability is normally prioritised','That all courts can freely ignore precedent at any time','That judicial decisions are entirely subjective'], ans:1, topic:'Argument Analysis', hint:'"In exceptional circumstances where it is right to do so" — this preserves flexibility for legal development while maintaining the rule that departure is the exception, not the norm. Law must be able to correct its own errors.', difficulty:2, tags:[] },

  // ── Passage 22: Tort Law ─────────────────────────────────────────────────
  { id:'lnat_106', q:'Passage: "Negligence requires proof of three elements: a duty of care, breach of that duty, and damage caused by the breach. The neighbour principle from Donoghue v Stevenson establishes that we owe a duty of care to those who might foreseeably be affected by our actions. A defendant is in breach if their conduct fell below the standard of the reasonable person. Pure economic loss is generally not recoverable in negligence — the claimant must have suffered physical injury or property damage."\n\nWhich three elements must a claimant prove in a negligence claim?', opts:['Intent, injury, and witnesses','Duty of care, breach of that duty, and resulting damage','A contract, a promise, and a broken promise','Foreseeability, remoteness, and intention'], ans:1, topic:'Argument Analysis', hint:'"A duty of care, breach of that duty, and damage caused by the breach" — these are the three elements of negligence. All three must be established.', difficulty:1, tags:[] },
  { id:'lnat_107', q:'Same passage. What is the standard against which breach of duty is measured?', opts:['The standard of the defendant\'s professional training','The standard of the specific person involved in the case','The standard of the reasonable person','The standard set by the judge in each case'], ans:2, topic:'Argument Analysis', hint:'"Their conduct fell below the standard of the reasonable person" — an objective standard, not based on the individual defendant\'s actual capabilities or intentions, but what a reasonable person would have done.', difficulty:1, tags:[] },
  { id:'lnat_108', q:'Same passage. Why is pure economic loss generally not recoverable in negligence?', opts:['Because economic loss is too large to compensate','Because the law limits negligence claims to cases involving physical injury or property damage, not purely financial harm','Because economic loss is always the claimant\'s own fault','Because economic loss claims are dealt with by contract law only'], ans:1, topic:'Argument Analysis', hint:'"Pure economic loss is generally not recoverable — the claimant must have suffered physical injury or property damage." Policy reasons: floodgates of litigation, distinguishing from contract law, limiting liability.', difficulty:2, tags:[] },

  // ── Passage 23: Proportionality and Human Rights ──────────────────────────
  { id:'lnat_109', q:'Passage: "Under human rights law, many rights are qualified — they can be limited by the state, but only if the limitation is prescribed by law, pursues a legitimate aim, is necessary in a democratic society, and is proportionate to the aim pursued. Proportionality requires that the means chosen are suitable to achieve the aim, that no less restrictive alternative was available, and that the harm caused is not excessive relative to the benefit achieved."\n\nUnder the proportionality test, what must be true about the means chosen by the state?', opts:['They must be the cheapest option available','They must be suitable to achieve the aim, no less restrictive alternative must be available, and the harm must not be excessive relative to the benefit','They must be approved by Parliament in advance','They must have been used in other countries'], ans:1, topic:'Argument Analysis', hint:'Three components of proportionality: (1) suitability — the means can achieve the aim; (2) necessity — least restrictive means; (3) balancing — harm not excessive relative to benefit. All three must be satisfied.', difficulty:2, tags:[] },
  { id:'lnat_110', q:'Same passage. If a state bans all political protests in order to prevent minor inconvenience to traffic, this would likely fail proportionality because:', opts:['Political protests are always legal','Banning all protests is suitable but may be unnecessary (less restrictive alternatives exist, e.g. time/place restrictions) and the harm (suppression of expression) is excessive relative to the minor benefit (traffic convenience)','The government did not consult Parliament','It was not prescribed by law'], ans:1, topic:'Argument Analysis', hint:'Applying the test: suitable (banning protests would prevent traffic disruption) but NOT necessary (less restrictive alternatives exist) and NOT proportionate (complete ban on expression for minor traffic convenience). Fails the last two elements.', difficulty:2, tags:[] },
  { id:'lnat_111', q:'Same passage. What does "prescribed by law" mean as a requirement for limiting rights?', opts:['The limitation must be decided by a judge','The limitation must be authorised by a sufficiently clear legal rule accessible to citizens, so they can foresee when and how their rights may be limited','The limitation must be written in a constitution','The limitation must be approved by a referendum'], ans:1, topic:'Argument Analysis', hint:'"Prescribed by law" in human rights law requires that the limitation has a legal basis that is accessible and foreseeable — citizens should be able to know what the rules are. Arbitrary, secret, or unpredictable restrictions fail this requirement.', difficulty:2, tags:[] },

  // ── Passage 24: Equality and Discrimination ───────────────────────────────
  { id:'lnat_112', q:'Passage: "Discrimination law distinguishes between direct and indirect discrimination. Direct discrimination is treating someone less favourably because of a protected characteristic. Indirect discrimination occurs where a seemingly neutral rule or practice puts a group with a protected characteristic at a particular disadvantage. Indirect discrimination can be justified if the practice pursues a legitimate aim proportionately. Direct discrimination, with certain exceptions, cannot be justified."\n\nWhat is the key difference between direct and indirect discrimination?', opts:['Direct discrimination is more common than indirect','Direct discrimination is intentional; indirect discrimination is always unintentional','Direct discrimination is less favourable treatment because of a protected characteristic; indirect discrimination is a neutral rule that disproportionately disadvantages a protected group','Direct discrimination is unlawful; indirect discrimination is always lawful'], ans:2, topic:'Argument Analysis', hint:'"Direct = treating someone less favourably because of a protected characteristic." "Indirect = neutral rule that puts a protected group at particular disadvantage." Key: directness of the link between characteristic and treatment.', difficulty:2, tags:[] },
  { id:'lnat_113', q:'Same passage. An employer requires all staff to be available for Saturday shifts as a condition of employment. This has a disproportionate impact on Jewish and Muslim employees whose faith requires rest or worship on Saturday/Friday. What type of discrimination does this most likely constitute?', opts:['Direct discrimination on grounds of religion','Indirect discrimination — a neutral-looking rule that puts religious groups at a particular disadvantage','No discrimination — all employees face the same requirement','Direct discrimination on grounds of race'], ans:1, topic:'Argument Analysis', hint:'The rule is facially neutral (applies to all) but puts those whose religion prohibits Saturday work at a particular disadvantage. This is textbook indirect discrimination.', difficulty:2, tags:[] },
  { id:'lnat_114', q:'Same passage. Can indirect discrimination ever be justified?', opts:['Never — like direct discrimination, it can never be justified','Yes — if the practice pursues a legitimate aim and is proportionate in how it achieves that aim','Only if Parliament has specifically authorised it','Only in employment cases, not in the provision of services'], ans:1, topic:'Argument Analysis', hint:'"Indirect discrimination can be justified if the practice pursues a legitimate aim proportionately." Unlike direct discrimination (generally unjustifiable), indirect can be justified if necessary and proportionate.', difficulty:1, tags:[] },

  // ── Additional mixed passage questions ────────────────────────────────────
  { id:'lnat_115', q:'Passage: "Restorative justice focuses on repairing the harm caused by criminal behaviour rather than punishing the offender. It typically involves mediated meetings between offenders and victims. Studies suggest it can reduce reoffending and increase victim satisfaction compared to traditional court processes. Critics argue it may place undue pressure on victims to participate, and that serious crimes require a stronger public statement of condemnation than restorative processes offer."\n\nWhat do studies suggest about restorative justice?', opts:['That it increases reoffending','That it consistently produces worse outcomes than traditional courts','That it can reduce reoffending and increase victim satisfaction relative to traditional court processes','That victims always prefer traditional courts'], ans:2, topic:'Argument Analysis', hint:'"Studies suggest it can reduce reoffending and increase victim satisfaction compared to traditional court processes." Note "can" — this is a positive but measured claim.', difficulty:1, tags:[] },
  { id:'lnat_116', q:'Same passage. What criticism do opponents of restorative justice raise about serious crimes?', opts:['That it is too expensive','That victims of serious crimes are too traumatised to participate','That serious crimes require a stronger public denunciation than restorative processes provide','That offenders refuse to participate in mediation'], ans:2, topic:'Argument Analysis', hint:'"Serious crimes require a stronger public statement of condemnation than restorative processes offer." The argument is about the expressive function of punishment — public condemnation, not just harm repair.', difficulty:2, tags:[] },
  { id:'lnat_117', q:'Passage: "Utilitarianism holds that the right action is that which maximises overall happiness or wellbeing. Its appeal lies in its impartiality — everyone\'s happiness counts equally — and its practical focus on consequences. Critics argue it fails to protect individual rights: if torturing one person would prevent great suffering for many, utilitarianism seemingly requires it. John Rawls offered an influential alternative — justice as fairness — arguing that just principles are those a rational person would choose from behind a \'veil of ignorance\' about their own position in society."\n\nWhat is the utilitarian criterion for a right action?', opts:['That it respects individual rights above all','That it follows a universal moral law','That it maximises overall happiness or wellbeing','That it is chosen freely by rational agents'], ans:2, topic:'Argument Analysis', hint:'"The right action is that which maximises overall happiness or wellbeing." This is the utilitarian principle (Bentham, Mill). The focus is on aggregate welfare, not rights or duties.', difficulty:1, tags:[] },
  { id:'lnat_118', q:'Same passage. What is the "veil of ignorance" in Rawls\'s theory?', opts:['A metaphor for human ignorance in general','The idea that principles of justice should be chosen by rational persons who do not know their own place in society — ensuring impartiality','The principle that judges must be blind to the race of defendants','A device for hiding information from juries'], ans:1, topic:'Argument Analysis', hint:'"Behind a \'veil of ignorance\' about their own position in society" — the veil prevents you knowing your class, wealth, abilities, etc. This ensures you choose principles you would find fair regardless of where you end up.', difficulty:2, tags:[] },
  { id:'lnat_119', q:'Passage: "Legal positivism holds that law is a social fact — what counts as law is determined by the sources through which it was made (legislation, precedent), not by its moral content. A law may be unjust yet still be law. This is distinct from natural law theory, which holds that unjust laws are not true laws — lex iniusta non est lex (an unjust law is not a law). The debate has significant practical implications: a judge under positivism must apply an unjust law; under natural law, they may be permitted — or required — to refuse."\n\nAccording to legal positivism, what makes something "law"?', opts:['Its moral content — it must be just to be law','Its social source — whether it was made through the correct legal procedures','Whether it is widely obeyed by citizens','Whether it was approved by a court'], ans:1, topic:'Argument Analysis', hint:'"Law is a social fact — what counts as law is determined by the sources through which it was made." Source, not moral quality, is the criterion. Law can be unjust and still be law under positivism.', difficulty:1, tags:[] },
  { id:'lnat_120', q:'Same passage. What is the practical implication for a judge of the natural law position?', opts:['The judge must always apply positive law regardless of its content','The judge may or must refuse to apply a law that is sufficiently unjust — unjust laws lack true legal authority','The judge can never override the legislature','The judge must consult moral philosophers before deciding cases'], ans:1, topic:'Argument Analysis', hint:'"Under natural law, they may be permitted — or required — to refuse." If an unjust law is not true law, a judge is not bound by it. This has been invoked in debates about resistance to Nazi law and apartheid.', difficulty:2, tags:[] },
  { id:'lnat_121', q:'Passage: "Access to justice is widely considered a fundamental component of the rule of law. However, legal aid cuts in England and Wales since 2013 have significantly reduced the availability of publicly funded legal advice and representation. Without legal assistance, many litigants in person struggle to navigate complex legal procedures effectively. Research suggests that unrepresented parties are significantly less likely to achieve favourable outcomes, raising concerns about inequality before the law."\n\nWhat concern does the passage raise about legal aid cuts?', opts:['That legal aid was too expensive for the government','That reducing legal aid may undermine equality before the law by creating a justice gap for those who cannot afford representation','That lawyers are overpaid under the legal aid scheme','That courts are too slow to process cases with unrepresented parties'], ans:1, topic:'Argument Analysis', hint:'"Unrepresented parties are significantly less likely to achieve favourable outcomes, raising concerns about inequality before the law." The argument is that legal aid cuts create a justice gap — unequal access to justice based on wealth.', difficulty:1, tags:[] },
  { id:'lnat_122', q:'Passage: "Mediation is a form of alternative dispute resolution in which a neutral third party helps disputing parties reach a mutually acceptable settlement. It is voluntary, confidential, and without prejudice — statements made cannot be used in subsequent litigation. Mediation can be faster and cheaper than litigation, and preserves ongoing relationships better than adversarial proceedings. Critics argue it is unsuitable where there is a significant power imbalance between parties, as the weaker party may accept an unfair settlement."\n\nWhat is the main criticism of mediation in cases of power imbalance?', opts:['Mediation is too slow','Mediation is too expensive','The weaker party may accept an unfair outcome rather than escalate to litigation','Mediators are not legally qualified'], ans:2, topic:'Argument Analysis', hint:'"The weaker party may accept an unfair settlement." If one party has significantly more resources, legal knowledge, or leverage, the "voluntary" agreement may reflect coercion or inequality of bargaining power.', difficulty:1, tags:[] },
  { id:'lnat_142', q:'Passage: "The doctrine of parliamentary sovereignty holds that Parliament can make or unmake any law, and no court can override its legislation. However, Brexit and the UK\'s departure from the EU, along with Human Rights Act litigation, have raised questions about whether sovereignty remains absolute in practice. Courts have struck down secondary legislation as incompatible with human rights, though they cannot strike down primary legislation — only issue a declaration of incompatibility."\n\nWhat can UK courts do when primary legislation is incompatible with human rights?', opts:['Strike it down and declare it invalid','Rewrite the legislation themselves','Issue a declaration of incompatibility — they cannot strike down primary legislation','Refer the matter to the European Court of Justice'], ans:2, topic:'Argument Analysis', hint:'"Courts cannot strike down primary legislation — only issue a declaration of incompatibility." Under the HRA 1998, s.4, a declaration of incompatibility does not invalidate the legislation; Parliament retains sovereignty to decide whether to amend it.', difficulty:2, tags:[] },
]
